# The outputs `division_solve_golden` holds bit for bit: the division camera solve
# on representative DivisionBoards scenes, flattened to named Float64 vectors (an
# iteration count is exact in a Float64). Included by the test item, and by
# whoever regenerates `division_solve_golden.jl` from code they trust:
#     include("division_solve_golden_record.jl"); _golden_literals(golden_record())
using StableRNGs: StableRNG
using StaticArrays: SVector
using Rotations: RotXYZ
using VisualGeometryToolkitCore: RadialCamera, CameraModel, CspondNormalization, Csponds, intrinsics, lens,
    focal_length, parameter_vector, iterations, estimate, rotation, translation
using VisualGeometryToolkitEstimation: DivisionCameraState, fit_division_camera, division_camera_step

# A state's f, k and every pose (rotation column-major, then translation), by view key.
function _golden_state!(out, name, st::DivisionCameraState)
    push!(out, "$name.f" => [st.f])
    push!(out, "$name.k" => collect(Float64, st.k))
    for id in sort!(collect(keys(st.poses)))
        p = st.poses[id]
        push!(out, "$name.pose[$id]" => vcat(vec(Matrix(rotation(p))), collect(translation(p))))
    end
    return out
end

function _golden_fit!(out, name, res)
    cam = estimate(res)
    push!(out, "$name.focal" => collect(Float64, focal_length(intrinsics(cam))))
    push!(out, "$name.coefficients" => collect(Float64, parameter_vector(lens(cam))))
    _golden_state!(out, "$name.state", res.state)
    push!(out, "$name.sigma" => [res.sigma])
    push!(out, "$name.nu" => [res.ν])
    push!(out, "$name.iterations" => [Float64(iterations(res))])
    for id in sort!(collect(keys(res.views)))
        push!(out, "$name.weights[$id]" => collect(Float64, res.views[id].weights))
    end
    return out
end

function golden_record()
    out = Pair{String, Vector{Float64}}[]
    cams = [board_camera(RotXYZ(a...), t) for (a, t) in zip(BOARD_ANGLES, BOARD_TS)]
    rc = Dict(enumerate(RadialCamera.(cams)))
    sz = (4000, 3000)
    # clean: pixel noise only
    clean, _ = noisy_board_views(StableRNG(11), cams; σ = 0.4)
    vclean = Dict(enumerate(clean))
    _golden_fit!(out, "clean", fit_division_camera(rc, vclean; image_size = sz))
    # contaminated: 8 % gross outliers (fit_division_camera_tests' scene), one and two coefficients
    dirty, _ = noisy_board_views(StableRNG(3), cams; σ = 0.4, ε = 0.08)
    vdirty = Dict(enumerate(dirty))
    _golden_fit!(out, "contaminated", fit_division_camera(rc, vdirty; image_size = sz))
    _golden_fit!(out, "contaminated2", fit_division_camera(rc, vdirty; image_size = sz, ncoef = 2))
    # known k
    _golden_fit!(out, "known_k", fit_division_camera(rc, vdirty; image_size = sz, k = K0))
    # one step: plain rows, and whitened at a seed under prior weights
    N = CspondNormalization(DivisionCameraState, vdirty; center = SVector(0.0, 0.0))
    _golden_state!(out, "step_plain", division_camera_step(N, rc, vdirty))
    wv = Dict(i => Csponds(first.(b), last.(b); weights = fill(Float64(i), length(b))) for (i, b) in enumerate(dirty))
    Nw = CspondNormalization(DivisionCameraState, wv; center = SVector(0.0, 0.0))
    _golden_state!(out, "step_seeded", division_camera_step(Nw, rc, wv; whiten_at = 2500.0))
    return out
end

# The fixture's source text: every value as its shortest round-tripping literal.
function _golden_literals(rec)
    io = IOBuffer()
    println(io, "# GENERATED by test/fixtures/division_solve_golden_record.jl (`_golden_literals(golden_record())`)")
    println(io, "# against the division camera solve before its arrow elimination was generalized; do not edit.")
    # where the bits were recorded: the item holds them `===` only there
    println(io, "const DIVISION_SOLVE_GOLDEN_JULIA = ", repr(VERSION))
    println(io, "const DIVISION_SOLVE_GOLDEN_CPU = ", repr(Sys.CPU_NAME))
    println(io, "const DIVISION_SOLVE_GOLDEN = Pair{String, Vector{Float64}}[")
    for (k, v) in rec
        println(io, "    ", repr(k), " => [", join((repr(x) for x in v), ", "), "],")
    end
    println(io, "]")
    return String(take!(io))
end
